import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#work', label: 'Work' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-background/90 backdrop-blur-md border-b border-border/30'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Alex Morgan"
              className="h-9 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="relative text-sm font-medium tracking-wide text-muted-foreground hover:text-foreground transition-colors duration-200 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-200 group-hover:w-full" />
              </button>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border/30 py-6">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-sm font-medium tracking-wide text-muted-foreground hover:text-foreground transition-colors text-left py-1"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <footer className="border-t border-border/20 bg-background">
      <div className="max-w-7xl mx-auto px-6 md:px-12 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center gap-3">
          <p className="text-sm text-muted-foreground tracking-wide">
            © {currentYear} Alex Morgan. All rights reserved.
          </p>
          <button
            onClick={scrollToTop}
            className="text-sm text-muted-foreground hover:text-primary transition-colors duration-200 tracking-wide group flex items-center gap-1.5"
          >
            Back to top
            <span className="inline-block transition-transform duration-200 group-hover:-translate-y-0.5">↑</span>
          </button>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, Dribbble, ArrowDown, Mail } from 'lucide-react';

// ─── Animation Variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, delay, ease: 'easeOut' as const },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const },
  },
};

// ─── Decorative SVG Elements ──────────────────────────────────────────────────

function GeometricLines() {
  return (
    <svg
      className="absolute right-0 top-1/2 -translate-y-1/2 w-[480px] h-[480px] opacity-20 pointer-events-none select-none hidden lg:block"
      viewBox="0 0 480 480"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      {/* Outer circle */}
      <circle cx="240" cy="240" r="200" stroke="#D4A847" strokeWidth="0.5" />
      {/* Inner circle */}
      <circle cx="240" cy="240" r="140" stroke="#D4A847" strokeWidth="0.5" />
      {/* Cross lines */}
      <line x1="40" y1="240" x2="440" y2="240" stroke="#D4A847" strokeWidth="0.5" />
      <line x1="240" y1="40" x2="240" y2="440" stroke="#D4A847" strokeWidth="0.5" />
      {/* Diagonal lines */}
      <line x1="98" y1="98" x2="382" y2="382" stroke="#D4A847" strokeWidth="0.5" />
      <line x1="382" y1="98" x2="98" y2="382" stroke="#D4A847" strokeWidth="0.5" />
      {/* Dots at intersections */}
      <circle cx="240" cy="40" r="3" fill="#D4A847" />
      <circle cx="240" cy="440" r="3" fill="#D4A847" />
      <circle cx="40" cy="240" r="3" fill="#D4A847" />
      <circle cx="440" cy="240" r="3" fill="#D4A847" />
      <circle cx="98" cy="98" r="3" fill="#D4A847" />
      <circle cx="382" cy="98" r="3" fill="#D4A847" />
      <circle cx="98" cy="382" r="3" fill="#D4A847" />
      <circle cx="382" cy="382" r="3" fill="#D4A847" />
      {/* Center dot */}
      <circle cx="240" cy="240" r="4" fill="#D4A847" />
      {/* Small square */}
      <rect x="220" y="220" width="40" height="40" stroke="#D4A847" strokeWidth="0.5" />
    </svg>
  );
}

function AboutDecoration() {
  return (
    <svg
      className="w-full max-w-xs opacity-25 mx-auto"
      viewBox="0 0 300 400"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      {/* Portrait frame */}
      <rect x="20" y="20" width="260" height="360" stroke="#D4A847" strokeWidth="0.8" />
      <rect x="35" y="35" width="230" height="330" stroke="#D4A847" strokeWidth="0.4" />
      {/* Corner accents */}
      <line x1="20" y1="60" x2="50" y2="60" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="20" y1="20" x2="20" y2="60" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="250" y1="20" x2="280" y2="20" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="280" y1="20" x2="280" y2="60" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="20" y1="340" x2="20" y2="380" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="20" y1="380" x2="50" y2="380" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="280" y1="340" x2="280" y2="380" stroke="#D4A847" strokeWidth="1.5" />
      <line x1="250" y1="380" x2="280" y2="380" stroke="#D4A847" strokeWidth="1.5" />
      {/* Inner geometric */}
      <circle cx="150" cy="200" r="80" stroke="#D4A847" strokeWidth="0.4" />
      <circle cx="150" cy="200" r="40" stroke="#D4A847" strokeWidth="0.4" />
      <line x1="70" y1="200" x2="230" y2="200" stroke="#D4A847" strokeWidth="0.4" />
      <line x1="150" y1="120" x2="150" y2="280" stroke="#D4A847" strokeWidth="0.4" />
      {/* Dots */}
      <circle cx="150" cy="120" r="2.5" fill="#D4A847" />
      <circle cx="150" cy="280" r="2.5" fill="#D4A847" />
      <circle cx="70" cy="200" r="2.5" fill="#D4A847" />
      <circle cx="230" cy="200" r="2.5" fill="#D4A847" />
      <circle cx="150" cy="200" r="4" fill="#D4A847" />
    </svg>
  );
}

// ─── Dot Grid Background ──────────────────────────────────────────────────────

function DotGrid() {
  return (
    <div
      className="absolute inset-0 pointer-events-none select-none"
      style={{
        backgroundImage: 'radial-gradient(circle, rgba(212,168,71,0.15) 1px, transparent 1px)',
        backgroundSize: '32px 32px',
      }}
      aria-hidden="true"
    />
  );
}

// ─── Social Links ─────────────────────────────────────────────────────────────

const socialLinks = [
  { icon: Github, href: 'https://github.com', label: 'GitHub' },
  { icon: Linkedin, href: 'https://linkedin.com', label: 'LinkedIn' },
  { icon: Twitter, href: 'https://twitter.com', label: 'Twitter / X' },
  { icon: Dribbble, href: 'https://dribbble.com', label: 'Dribbble' },
];

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  const scrollTo = (id: string) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer & Developer</title>
        <meta
          name="description"
          content="Personal portfolio of Alex Morgan — a designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section
        className="relative min-h-screen flex items-center overflow-hidden bg-background"
        style={{
          backgroundImage: `url('/airo-assets/images/pages/home/hero-bg')`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
        }}
      >
        {/* Dark overlay */}
        <div className="absolute inset-0 bg-background/85" aria-hidden="true" />
        {/* Dot grid texture */}
        <DotGrid />
        {/* Geometric accent */}
        <GeometricLines />

        <div className="relative z-10 max-w-7xl mx-auto px-6 md:px-12 w-full pt-24 pb-20">
          {/* Eyebrow */}
          <motion.p
            className="text-primary text-sm font-medium tracking-[0.2em] uppercase mb-6"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.1}
          >
            Designer & Developer
          </motion.p>

          {/* Name — oversized display */}
          <motion.h1
            className="font-heading text-[clamp(3.5rem,10vw,9rem)] leading-[0.92] tracking-tight text-foreground mb-8 max-w-4xl"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.25}
          >
            Alex
            <br />
            <span className="text-primary">Morgan.</span>
          </motion.h1>

          {/* Tagline */}
          <motion.p
            className="text-lg md:text-xl text-muted-foreground font-light max-w-md leading-relaxed mb-12"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.4}
          >
            I craft thoughtful digital experiences — where precision meets creativity and every
            pixel has a purpose.
          </motion.p>

          {/* CTAs */}
          <motion.div
            className="flex flex-wrap items-center gap-6"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.55}
          >
            <button
              onClick={() => scrollTo('work')}
              className="inline-flex items-center gap-2 bg-primary text-background px-7 py-3.5 text-sm font-medium tracking-wide hover:bg-primary/90 transition-colors duration-200"
            >
              View Work
            </button>
            <button
              onClick={() => scrollTo('contact')}
              className="relative text-sm font-medium tracking-wide text-foreground group"
            >
              Get in touch
              <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-foreground transition-all duration-200 group-hover:w-full" />
            </button>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.button
          onClick={() => scrollTo('about')}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-muted-foreground hover:text-primary transition-colors duration-200"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1, transition: { delay: 1, duration: 0.6 } }}
          aria-label="Scroll to about"
        >
          <span className="text-xs tracking-[0.15em] uppercase">Scroll</span>
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' }}
          >
            <ArrowDown size={16} />
          </motion.div>
        </motion.button>
      </section>

      {/* ── ABOUT ────────────────────────────────────────────────────────── */}
      <section id="about" className="py-28 md:py-36 bg-muted/30">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          <motion.div
            className="grid grid-cols-1 lg:grid-cols-2 gap-16 lg:gap-24 items-center"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-80px' }}
          >
            {/* Left — Text */}
            <div>
              {/* Section label */}
              <p className="text-primary text-xs font-medium tracking-[0.2em] uppercase mb-6">
                About
              </p>
              <h2 className="font-heading text-4xl md:text-5xl text-foreground leading-tight mb-10">
                Building with intention,
                <br />
                <span className="text-primary">designing with care.</span>
              </h2>

              <div className="space-y-8">
                <div>
                  <h3 className="text-xs font-medium tracking-[0.15em] uppercase text-muted-foreground mb-3">
                    Background
                  </h3>
                  <p className="text-muted-foreground leading-relaxed">
                    I'm a multidisciplinary designer and developer with over 8 years of experience
                    building products for startups and established brands alike. My work lives at
                    the intersection of visual design and engineering — I care deeply about both
                    how things look and how they work.
                  </p>
                </div>

                <div>
                  <h3 className="text-xs font-medium tracking-[0.15em] uppercase text-muted-foreground mb-3">
                    Currently working on
                  </h3>
                  <p className="text-muted-foreground leading-relaxed">
                    Exploring the boundaries of generative design systems and building tools that
                    help creative teams move faster without sacrificing quality. Open to select
                    freelance projects and collaborations.
                  </p>
                </div>

                {/* Skills row */}
                <div className="flex flex-wrap gap-3 pt-2">
                  {['UI/UX Design', 'React', 'TypeScript', 'Motion', 'Figma', 'Node.js'].map(
                    (skill) => (
                      <span
                        key={skill}
                        className="text-xs tracking-wide text-muted-foreground border border-border/50 px-3 py-1.5"
                      >
                        {skill}
                      </span>
                    )
                  )}
                </div>
              </div>
            </div>

            {/* Right — Decorative */}
            <div className="flex items-center justify-center lg:justify-end">
              <AboutDecoration />
            </div>
          </motion.div>
        </div>
      </section>

      {/* ── WORK PLACEHOLDER ─────────────────────────────────────────────── */}
      <section id="work" className="py-28 md:py-36 bg-background">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-80px' }}
          >
            <p className="text-primary text-xs font-medium tracking-[0.2em] uppercase mb-6">
              Selected Work
            </p>
            <h2 className="font-heading text-4xl md:text-5xl text-foreground leading-tight mb-16">
              Projects & case studies.
            </h2>

            {/* Placeholder cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-px bg-border/20">
              {[
                { title: 'Brand Identity System', category: 'Branding / Design', year: '2025' },
                { title: 'SaaS Dashboard', category: 'Product / Engineering', year: '2025' },
                { title: 'E-commerce Redesign', category: 'UX / Frontend', year: '2024' },
                { title: 'Mobile App', category: 'Design / React Native', year: '2024' },
              ].map((project) => (
                <div
                  key={project.title}
                  className="group relative bg-background border border-border/20 p-10 hover:border-primary/40 transition-colors duration-300 cursor-pointer"
                >
                  <div className="flex items-start justify-between mb-8">
                    <span className="text-xs text-muted-foreground tracking-[0.15em] uppercase">
                      {project.category}
                    </span>
                    <span className="text-xs text-muted-foreground">{project.year}</span>
                  </div>
                  <h3 className="font-heading text-2xl text-foreground group-hover:text-primary transition-colors duration-200 mb-4">
                    {project.title}
                  </h3>
                  <div className="flex items-center gap-2 text-xs text-muted-foreground group-hover:text-primary transition-colors duration-200">
                    <span>View project</span>
                    <span className="transition-transform duration-200 group-hover:translate-x-1">→</span>
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        </div>
      </section>

      {/* ── CONTACT ──────────────────────────────────────────────────────── */}
      <section id="contact" className="py-28 md:py-36 bg-muted/30">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          <motion.div
            className="max-w-2xl"
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: '-80px' }}
          >
            <p className="text-primary text-xs font-medium tracking-[0.2em] uppercase mb-6">
              Contact
            </p>
            <h2 className="font-heading text-5xl md:text-6xl text-foreground leading-tight mb-8">
              Get in touch.
            </h2>
            <p className="text-muted-foreground leading-relaxed mb-12 max-w-md">
              Have a project in mind or just want to say hello? I'm always open to interesting
              conversations and new collaborations.
            </p>

            {/* Email link */}
            <a
              href="mailto:hello@alexmorgan.design"
              className="group inline-flex items-center gap-3 text-foreground hover:text-primary transition-colors duration-200 mb-14"
            >
              <Mail size={18} className="shrink-0" />
              <span className="relative text-lg font-medium">
                hello@alexmorgan.design
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-200 group-hover:w-full" />
              </span>
            </a>

            {/* Divider */}
            <div className="w-12 h-px bg-border/40 mb-10" />

            {/* Social icons */}
            <div className="flex items-center gap-6">
              {socialLinks.map(({ icon: Icon, href, label }) => (
                <a
                  key={label}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={label}
                  className="text-muted-foreground hover:text-primary transition-all duration-150 hover:scale-110"
                >
                  <Icon size={20} />
                </a>
              ))}
            </div>
          </motion.div>
        </div>
      </section>
    </>
  );
}

